import{_ as e,o as a,c as d,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"前端出身学习路线（Vue/TS → Nest）","description":"给会 Vue 3 与 TypeScript、几乎没有 Nest/后端经验的读者：裁剪必读篇目、后端补课顺序、黄金路径验收与明确可跳过内容","frontmatter":{"title":"前端出身学习路线（Vue/TS → Nest）","description":"给会 Vue 3 与 TypeScript、几乎没有 Nest/后端经验的读者：裁剪必读篇目、后端补课顺序、黄金路径验收与明确可跳过内容","article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"ts-ai/appendix/learning/frontend-backend-learning-path.md","filePath":"ts-ai/appendix/learning/frontend-backend-learning-path.md","lastUpdated":1786166505000}'),r={name:"ts-ai/appendix/learning/frontend-backend-learning-path.md"};function s(o,t,i,l,c,p){return a(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="前端出身学习路线-vue-ts-→-nest" tabindex="-1">前端出身学习路线（Vue/TS → Nest） <a class="header-anchor" href="#前端出身学习路线-vue-ts-→-nest" aria-label="Permalink to &quot;前端出身学习路线（Vue/TS → Nest）&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本页是<a href="/ts-ai/appendix/learning/learning-roadmap">学习路线图</a>的<strong>裁剪版</strong>，专为下列读者：</p><ul><li>已能独立写 Vue 3（Composition API）与 TypeScript 业务页面</li><li>熟悉浏览器侧异步、<code>fetch</code>、组件状态</li><li><strong>几乎没写过 NestJS / 服务端 ORM / 队列</strong>，或不习惯「密钥只在服务端」的边界</li></ul><p>目标不是读完全部 200+ 篇，而是先交付一条可演示的全栈壳：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 Nuxt Chat</span></span>
<span class="line"><span>  →（代理）Nest Guard + DTO</span></span>
<span class="line"><span>  → Model Gateway（密钥不出前端）</span></span>
<span class="line"><span>  → 产品 SSE 事件</span></span>
<span class="line"><span>  → UI 流式渲染 / 取消</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>达标后你属于「AI 应用全栈 / 前端偏 AI」的初级–中级就绪；<strong>还不是</strong> RAG 专家或多 Agent 平台工程师——那是第二遍的事。</p><h2 id="_1-你已会什么、本册补什么" tabindex="-1">1. 你已会什么、本册补什么 <a class="header-anchor" href="#_1-你已会什么、本册补什么" aria-label="Permalink to &quot;1. 你已会什么、本册补什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你大概率已会</th><th>本路线强制补</th><th>第一遍不要碰</th></tr></thead><tbody><tr><td>Vue 3 组件与状态</td><td>Node 进程、环境变量、密钥边界</td><td>React/Next 扩展轨</td></tr><tr><td>TypeScript 与异步</td><td>Nest 请求管道、Module/DI 最小子集</td><td>A2A、Deep Agents、Swarm</td></tr><tr><td>调用过 HTTP API</td><td>Prisma：Thread/Run/Message</td><td>GraphRAG、多模态 RAG</td></tr><tr><td>前端错误与 loading</td><td>产品 SSE、取消、Run 状态</td><td>SLO、灰度、K8s、灾备全文</td></tr></tbody></table><p>语言缺口仍按<a href="/ts-ai/foundations/getting-started/agent-prerequisites-map">前置知识地图</a>自测；缺什么只补对应 frontend 手册章节，不要先啃完整 Nest 课。</p><h2 id="_2-黄金路径-约-6–8-周-必读" tabindex="-1">2. 黄金路径（约 6–8 周，必读） <a class="header-anchor" href="#_2-黄金路径-约-6–8-周-必读" aria-label="Permalink to &quot;2. 黄金路径（约 6–8 周，必读）&quot;">​</a></h2><p>按依赖顺序前进；每阶段满足「通过标准」再进入下一阶段。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A 模型地基          foundations</span></span>
<span class="line"><span>B 最小 Agent        agent（裁剪）</span></span>
<span class="line"><span>C 后端零基础特训    nestjs-core → ai-service 入门 → data 入门 → SSE</span></span>
<span class="line"><span>D 前端对接          integration 协议 + vue-nuxt 主线</span></span>
<span class="line"><span>E 可演示产品        实战 · AI 客服中心（验收 A1–A8）</span></span>
<span class="line"><span>F 质量最小集        单测 Fake + 鉴权/Injection 边界 + 日志 + Docker/CI 入门</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="a-模型地基" tabindex="-1">A. 模型地基 <a class="header-anchor" href="#a-模型地基" aria-label="Permalink to &quot;A. 模型地基&quot;">​</a></h3><table tabindex="0"><thead><tr><th>顺序</th><th>文章</th><th>你要带走的结果</th></tr></thead><tbody><tr><td>1</td><td><a href="/ts-ai/foundations/getting-started/agent-prerequisites-map">前置知识地图</a></td><td>自测通过或只补缺口</td></tr><tr><td>2</td><td><a href="/ts-ai/foundations/getting-started/create-typescript-ai-project">创建 TypeScript AI 项目</a></td><td><code>typecheck</code> / <code>test</code> 绿</td></tr><tr><td>3</td><td><a href="/ts-ai/foundations/getting-started/zod-minimum-introduction">Zod 最小入门</a></td><td>外部 JSON 先校验再进业务</td></tr><tr><td>4</td><td><a href="/ts-ai/foundations/model/">模型基础</a>（按组阅读）</td><td>理解不可信输出、错误可重试性</td></tr><tr><td>5</td><td><a href="/ts-ai/foundations/langchain-bridge/first-chatopenai-invoke">第一次 ChatOpenAI.invoke()</a></td><td>一次真调用或可配置调用</td></tr><tr><td>6</td><td><a href="/ts-ai/foundations/langchain-bridge/prompt-template-messages">PromptTemplate 与 Message</a></td><td><code>prompt.pipe(model)</code></td></tr><tr><td>7</td><td><a href="/ts-ai/foundations/langchain-bridge/zod-structured-output">Zod 结构化输出</a></td><td>Schema + 业务校验</td></tr><tr><td>8</td><td><a href="/ts-ai/foundations/langchain-bridge/model-call-tests">Fake、Mock 与错误测试</a></td><td><strong>只用 <code>fakeModel()</code></strong>，CI 不打真 API</td></tr></tbody></table><p><strong>通过标准：</strong> 能解释「类型通过 ≠ 运行时正确」；能用 <code>fakeModel()</code> 写一条失败用例。</p><h3 id="b-最小-agent-先别深挖百科" tabindex="-1">B. 最小 Agent（先别深挖百科） <a class="header-anchor" href="#b-最小-agent-先别深挖百科" aria-label="Permalink to &quot;B. 最小 Agent（先别深挖百科）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>顺序</th><th>文章</th><th>你要带走的结果</th></tr></thead><tbody><tr><td>1</td><td><a href="/ts-ai/agent/langchain-core/ecosystem-packages-versioning">生态、包与版本边界</a></td><td>知道从哪个包 import</td></tr><tr><td>2</td><td><a href="/ts-ai/agent/tools-mcp/tools-schemas">Tool 与 Schema</a></td><td><code>tool()</code> + Zod</td></tr><tr><td>3</td><td><a href="/ts-ai/agent/tools-mcp/tool-call-tool-message">Tool Call 与 ToolMessage</a></td><td>一轮工具闭环轨迹</td></tr><tr><td>4</td><td><a href="/ts-ai/agent/runtime/create-agent">使用 createAgent 创建 Agent</a></td><td>带工具的 <code>invoke</code></td></tr><tr><td>5</td><td><a href="/ts-ai/agent/runtime/streaming-cancellation-recovery">流式事件、取消与恢复</a></td><td>取消用 <code>AbortSignal</code>（流式 API 以本篇 + 产品 SSE 为准）</td></tr><tr><td>6</td><td><a href="/ts-ai/agent/assembly/assembly-recipes-checklist">Agent 组装配方</a></td><td>知道何时不要上 Agent</td></tr></tbody></table><p><strong>本阶段明确跳过（第二遍再学）：</strong> Runnable 组合百科深挖、MCP 全组、Middleware 细讲、Router/Planner、Agent vs Workflow 决策全文可扫一眼即可。</p><p><strong>通过标准：</strong> 能跑通「查订单」类工具 Agent，并用 Fake 断言出现了 <code>ToolMessage</code>。</p><h3 id="c-后端零基础特训-本路线核心" tabindex="-1">C. 后端零基础特训（本路线核心） <a class="header-anchor" href="#c-后端零基础特训-本路线核心" aria-label="Permalink to &quot;C. 后端零基础特训（本路线核心）&quot;">​</a></h3><p>从前端视角，先建立一张图：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器里：永远没有 OPENAI_API_KEY</span></span>
<span class="line"><span>Nuxt：UI + 可选 BFF 代理（附 Cookie/Token）</span></span>
<span class="line"><span>Nest：鉴权 → 校验 body → 调 Gateway/Agent → 写 Postgres → 推 SSE</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><table tabindex="0"><thead><tr><th>顺序</th><th>文章</th><th>你要带走的结果</th></tr></thead><tbody><tr><td>1</td><td><a href="/ts-ai/backend/nestjs-core/">NestJS 核心总览</a></td><td>人话管道图</td></tr><tr><td>2</td><td><a href="/ts-ai/backend/nestjs-core/project-structure-bootstrap">项目结构与启动</a></td><td><code>main.ts</code> 监听端口</td></tr><tr><td>3</td><td><a href="/ts-ai/backend/nestjs-core/minimal-agent-api-skeleton">最小可运行 Agent API</a></td><td><strong><code>curl</code> 出第一个 Run（先假 Agent）</strong></td></tr><tr><td>4</td><td><a href="/ts-ai/backend/nestjs-core/skeleton-to-modules">从 Skeleton 拆到 Module</a></td><td>拆 Auth/Runs Module，<strong>同一套 curl 仍过</strong></td></tr><tr><td>5</td><td><a href="/ts-ai/backend/nestjs-core/modules-providers-dependency-injection">Module、Provider 与 DI</a></td><td>理解 exports / 可测试替换</td></tr><tr><td>6</td><td><a href="/ts-ai/backend/nestjs-core/controllers-pipes-dto">Controller、Pipe 与 DTO</a></td><td>body 校验失败返回 400</td></tr><tr><td>7</td><td><a href="/ts-ai/backend/nestjs-core/guards-interceptors-filters">Guard、Interceptor 与 Filter</a></td><td>无 Token → 401</td></tr><tr><td>8</td><td><a href="/ts-ai/backend/nestjs-core/scopes-lifecycle">作用域与生命周期</a></td><td>默认 Singleton；别把请求用户塞进单例字段</td></tr><tr><td>9</td><td><a href="/ts-ai/backend/ai-service/nestjs-langchain-integration">NestJS 集成 LangChain.js</a></td><td>Agent 进 Provider，可被测试替换</td></tr><tr><td>10</td><td><a href="/ts-ai/backend/ai-service/model-gateway">Model Gateway</a></td><td>模型调用只经 Gateway</td></tr><tr><td>11</td><td><a href="/ts-ai/backend/data-tasks/thread-run-message-model">Thread、Run 与 Message</a></td><td>状态机心智</td></tr><tr><td>12</td><td><a href="/ts-ai/backend/data-tasks/postgresql-orm-migrations">PostgreSQL、ORM 与迁移</a></td><td><strong>Prisma</strong> Schema + migrate</td></tr><tr><td>13</td><td><a href="/ts-ai/backend/api-realtime/rest-agent-api">REST Agent API</a></td><td>创建 Run 的 HTTP 面</td></tr><tr><td>14</td><td><a href="/ts-ai/backend/api-realtime/sse-streaming">SSE 流式响应</a></td><td><code>text/event-stream</code>；映射为产品事件</td></tr><tr><td>15</td><td>（可选）<a href="/ts-ai/backend/data-tasks/bullmq-reliable-workers">BullMQ 与可靠 Worker</a></td><td>长任务进队列的一条配方</td></tr></tbody></table><p><strong>本阶段明确跳过：</strong> WebSocket 全文、OpenAPI 深讲、Redis 所有权全文、幂等恢复细文、Prompt 配置 YAML 生产化、多租户 ALS 深讲——等有工作台后再回看。</p><p><strong>通过标准：</strong></p><ul><li>[ ] <code>curl</code> 无 Token 得 401，有 Token 得 <code>runId</code></li><li>[ ] 能指出：密钥在哪个进程；浏览器 Network 里看不到 API Key</li><li>[ ] Postgres 里能查到对应 Thread/Run/Message 行</li></ul><h3 id="d-前端对接-你的主场" tabindex="-1">D. 前端对接（你的主场） <a class="header-anchor" href="#d-前端对接-你的主场" aria-label="Permalink to &quot;D. 前端对接（你的主场）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>顺序</th><th>文章</th><th>你要带走的结果</th></tr></thead><tbody><tr><td>1</td><td><a href="/ts-ai/integration/interaction-protocols/message-run-tool-call-events">Message、Run 与 Tool Call 事件</a></td><td><strong>唯一</strong> <code>ProductSseEvent</code> 形状（后面不要另起一套字段名）</td></tr><tr><td>2</td><td><a href="/ts-ai/integration/interaction-protocols/http-sse-websocket">HTTP、SSE 与 WebSocket</a></td><td>为何默认 SSE + <code>fetch</code>（Bearer）</td></tr><tr><td>3</td><td><a href="/ts-ai/integration/interaction-protocols/stream-event-parsing">流式事件解析</a></td><td>字节流 → 事件</td></tr><tr><td>4</td><td><a href="/ts-ai/integration/interaction-protocols/cancellation-reconnection-deduplication">取消、重连与去重</a></td><td>Abort + <code>Last-Event-ID</code></td></tr><tr><td>5</td><td><a href="/ts-ai/integration/vue-nuxt/minimal-ai-chat-ui">最小可运行 AI Chat UI</a></td><td>假事件流跑通状态机</td></tr><tr><td>6</td><td><a href="/ts-ai/integration/vue-nuxt/agent-chat-composable">Agent Chat Composable</a></td><td><code>useAgentChat</code></td></tr><tr><td>7</td><td><a href="/ts-ai/integration/vue-nuxt/nuxt-nestjs-integration">Nuxt 对接 NestJS</a></td><td>代理、鉴权头</td></tr><tr><td>8</td><td><a href="/ts-ai/integration/vue-nuxt/streaming-message-rendering">流式消息渲染</a></td><td>delta append</td></tr><tr><td>9</td><td>（按需）<a href="/ts-ai/integration/vue-nuxt/tool-call-ui">工具调用 UI</a></td><td>确认卡</td></tr></tbody></table><p><strong>本阶段明确跳过：</strong> React/Next 全组、Vercel AI SDK（除非团队强制）、ai-interaction 可当 UX 参考略读。</p><p><strong>通过标准：</strong> 假流与真 Nest SSE 共用同一套事件字段名；取消后不再追加 delta。</p><h3 id="e-可演示产品" tabindex="-1">E. 可演示产品 <a class="header-anchor" href="#e-可演示产品" aria-label="Permalink to &quot;E. 可演示产品&quot;">​</a></h3><table tabindex="0"><thead><tr><th>顺序</th><th>文章</th><th>你要带走的结果</th></tr></thead><tbody><tr><td>1</td><td><a href="/ts-ai/architecture/design-decisions/ts-ai-fullstack-architecture">TS-AI 全栈分层</a></td><td>六层归属</td></tr><tr><td>2</td><td><a href="/ts-ai/architecture/design-decisions/frontend-backend-state-ownership">前后端状态所有权</a></td><td>Run 真相在服务端</td></tr><tr><td>3</td><td><a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a></td><td>按章<strong>从 0 建造</strong>，章末对照 <code>examples/ts-ai/ai-customer-support/final</code>，勾 <strong>A1–A8</strong></td></tr><tr><td>4</td><td><a href="/ts-ai/integration/vue-nuxt/complete-ai-chat-project">AI Chat 拼装验收清单</a></td><td>当作<strong>验收拼装清单</strong>，不是 monorepo 源码包</td></tr></tbody></table><p><strong>通过标准（上岗最小证明）：</strong></p><ol><li>能画清：浏览器 → Nuxt 代理 → Nest → Gateway → 模型 → SSE → UI</li><li>密钥不在前端包里</li><li>能取消 Run，状态为 <code>cancelled</code></li><li>刷新后能拉到历史 Message</li><li>（加分）加一个只读 Tool，UI 能展示 <code>tool.*</code></li></ol><blockquote><p>AI 客服中心已有<strong>跟做分组</strong>（从 0 建造 7 章）；<code>examples/ts-ai/ai-customer-support/final</code> 为章末成品参考。P2–P5 项目正文待写，规划见架构与实战总览。</p></blockquote><h3 id="f-质量最小集-不要一次读完-quality-全书" tabindex="-1">F. 质量最小集（不要一次读完 quality 全书） <a class="header-anchor" href="#f-质量最小集-不要一次读完-quality-全书" aria-label="Permalink to &quot;F. 质量最小集（不要一次读完 quality 全书）&quot;">​</a></h3><p>本阶段是前端出身读者的裁剪清单，完整版见 <a href="/ts-ai/quality/">质量与生产 · 上岗最小集</a>；两处如有出入，以 quality 总览的上岗最小集为准。</p><table tabindex="0"><thead><tr><th>顺序</th><th>文章</th><th>目的</th></tr></thead><tbody><tr><td>1</td><td><a href="/ts-ai/foundations/langchain-bridge/model-call-tests">模型调用 Fake 测试</a> + <a href="/ts-ai/quality/testing-evaluation/agent-unit-testing">Agent 单元测试</a></td><td>CI 默认 Fake</td></tr><tr><td>2</td><td><a href="/ts-ai/quality/security-governance/authentication-authorization">认证与授权</a></td><td>Token / 角色边界</td></tr><tr><td>3</td><td><a href="/ts-ai/quality/security-governance/prompt-injection-defense">Prompt Injection 防护</a></td><td>外部内容 ≠ 授权</td></tr><tr><td>4</td><td><a href="/ts-ai/quality/observability-reliability/structured-logging">结构化日志</a></td><td><code>runId</code> / <code>tenantId</code> 可串联</td></tr><tr><td>5</td><td><a href="/ts-ai/quality/deployment-operations/configuration-secrets">配置与 Secret</a></td><td>Zod 校验 env</td></tr><tr><td>6</td><td><a href="/ts-ai/quality/deployment-operations/docker">Docker</a> + <a href="/ts-ai/quality/deployment-operations/ci-cd">CI/CD</a></td><td>可构建、可绿</td></tr></tbody></table><p>SLO、灰度、横向扩容、灾备：<strong>进公司有流量后再学</strong>。</p><h2 id="_3-第二遍再学-明确延后" tabindex="-1">3. 第二遍再学（明确延后） <a class="header-anchor" href="#_3-第二遍再学-明确延后" aria-label="Permalink to &quot;3. 第二遍再学（明确延后）&quot;">​</a></h2><p>有 AI 客服中心 A1–A8 之后，按业务选一条，不要并行多条：</p><table tabindex="0"><thead><tr><th>目标</th><th>入口</th></tr></thead><tbody><tr><td>知识库问答</td><td><a href="/ts-ai/knowledge/rag-foundations/rag-principles-boundaries">RAG 原理</a> → <a href="/ts-ai/knowledge/rag-foundations/minimal-rag-skeleton">最小 RAG</a> → P2 产品帮助中心问答（规划见 <a href="/ts-ai/architecture/">架构与实战总览</a>）</td></tr><tr><td>长任务 / 人机确认</td><td><a href="/ts-ai/workflow/workflow-foundations/minimal-stategraph-skeleton">最小 StateGraph</a> → <a href="/ts-ai/workflow/durable-execution/interrupt-command">Interrupt</a> → P3 深度研究报告（规划中）</td></tr><tr><td>查数 / MCP 治理</td><td>先客服中心，再 <a href="/ts-ai/agent/tools-mcp/">MCP</a> → P4 经营数据分析（规划中）</td></tr></tbody></table><h2 id="_4-学习时的硬规则-前端出身特别容易踩" tabindex="-1">4. 学习时的硬规则（前端出身特别容易踩） <a class="header-anchor" href="#_4-学习时的硬规则-前端出身特别容易踩" aria-label="Permalink to &quot;4. 学习时的硬规则（前端出身特别容易踩）&quot;">​</a></h2><ol><li><strong>测试 Fake 主路只用 <code>fakeModel()</code></strong>（见 foundations 测试篇）。遇到旧文 <code>FakeListChatModel</code>，视为遗留写法，优先改写成 <code>fakeModel()</code>。</li><li><strong>产品事件字段以协议篇为准</strong>，不要在 Nuxt 里另造 <code>toolName</code> / <code>tool.failed</code> 等同义字段。</li><li><strong>LangChain.js 主线是 v1（<code>createAgent</code>）</strong>，不要按「0.3+」去装旧包。</li><li><strong>一个贯穿仓库</strong>，不要每篇文章新建互不相关的 Demo。</li><li><strong>先假 Agent / Fake 模型，再接真 Key</strong>——否则你会分不清是 Nest 配错还是模型挂了。</li></ol><h2 id="_5-与总路线图的关系" tabindex="-1">5. 与总路线图的关系 <a class="header-anchor" href="#_5-与总路线图的关系" aria-label="Permalink to &quot;5. 与总路线图的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>用途</th></tr></thead><tbody><tr><td>本页</td><td>前端零后端读者的<strong>默认主线</strong></td></tr><tr><td><a href="/ts-ai/appendix/learning/learning-roadmap">学习路线图</a></td><td>完整阶段 0–8 与其他背景入口</td></tr><tr><td><a href="/ts-ai/appendix/learning/knowledge-checklist">知识点清单</a></td><td>查漏；不要第一遍按清单全勾</td></tr><tr><td><a href="/ts-ai/appendix/learning/common-misconceptions">常见误区</a></td><td>卡壳时对照</td></tr></tbody></table><p>下一步：打开 <a href="/ts-ai/backend/nestjs-core/">NestJS 核心</a>，从最小可 curl API 开始补后端。</p>`,48)])])}const g=e(r,[["render",s]]);export{u as __pageData,g as default};
